mapper.update:
UPDATE object_file
SET operation_status = #{status},
    last_error       = #{lastError},
    updated_at       = #{updatedAt}
WHERE bucket_name = #{bucket}
  AND object_key_hash = #{objectKeyHash}

mapper.delete:
DELETE
FROM object_file
WHERE bucket_name = #{bucket}
  AND object_key_hash = #{objectKeyHash}
